// Icons for the Design System (ADR-070 dec. 8: components deferred, icons now). Renders every icon
// component in src/ui/icons/ (the barrel index.ts excluded) with react-dom/server at size 16 into
// design/system/project/assets/Icons/<kebab-name>.svg, plus the group README.
//
// A separate script, not a Style Dictionary target: icons are not tokens, and SD has no input for
// TSX. It still runs inside `npm run tokens` (called from style-dictionary.config.mjs), so the DS is
// regenerated by one command. Each .tsx is transpiled in memory by the project's own TypeScript
// (CommonJS + react-jsx) and evaluated with a require scoped to client/ — no temp files, no build.
// Deterministic: sorted file list, no timestamp.
import ts from 'typescript'
import { createElement } from 'react'
import { renderToStaticMarkup } from 'react-dom/server'
import { mkdir, readdir, readFile, rm, writeFile } from 'node:fs/promises'
import { createRequire } from 'node:module'
import { fileURLToPath } from 'node:url'
import { dirname, join } from 'node:path'
import { DS_PROJECT_DIR } from './ds-tokens.mjs'

const clientRoot = join(dirname(fileURLToPath(import.meta.url)), '..')
const ICONS = join(clientRoot, 'src', 'ui', 'icons')
const require = createRequire(join(clientRoot, 'package.json'))

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase()

const README = `# Icons

Gerados dos componentes de \`client/src/ui/icons/\` por \`npm run tokens\` (tamanho 16).

O traço é single-ink em \`stroke="currentColor"\`: no client ele herda a cor do texto,
\`--color-text\`. Visto aqui por \`<img>\`, \`currentColor\` não herda nada e o traço aparece preto.

O cadeado (\`lock.svg\`) fala de acesso (quem foi adicionado ao canal), nunca de cifragem: um
canal público mostra \`#\`, não um cadeado aberto.
`

function loadComponent(file, source) {
  const { outputText } = ts.transpileModule(source, {
    compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX, target: ts.ScriptTarget.ES2022 },
    fileName: file,
  })
  const module = { exports: {} }
  new Function('require', 'module', 'exports', outputText)(require, module, module.exports)
  const fns = Object.entries(module.exports).filter(([, v]) => typeof v === 'function')
  if (fns.length !== 1) throw new Error(`ds-icons: ${file} must export exactly one component`)
  return fns[0]
}

/** Renders the icons into `<projectDir>/assets/Icons/`. Returns the written file names. */
export async function buildDsIcons(projectDir = DS_PROJECT_DIR) {
  const out = join(projectDir, 'assets', 'Icons')
  await rm(out, { recursive: true, force: true })
  await mkdir(out, { recursive: true })
  const files = (await readdir(ICONS)).filter((f) => f.endsWith('.tsx')).sort()
  const written = []
  for (const file of files) {
    const [name, Component] = loadComponent(file, await readFile(join(ICONS, file), 'utf8'))
    const markup = renderToStaticMarkup(createElement(Component, { size: 16 }))
    if (!markup.startsWith('<svg ') || !markup.includes('stroke="currentColor"')) {
      throw new Error(`ds-icons: ${file} did not render a currentColor <svg>`)
    }
    // A standalone .svg needs the namespace (inline JSX does not).
    const svg = markup.replace('<svg ', '<svg xmlns="http://www.w3.org/2000/svg" ') + '\n'
    const target = `${kebab(name)}.svg`
    await writeFile(join(out, target), svg)
    written.push(target)
  }
  await writeFile(join(out, 'README.md'), README)
  return written
}
